module xray_optimal_energies (input clk, input rst_n, input start, input [5:0] n, input [3:0] m, input [31:0] k_data, input [5:0] bin_index, input k_wr, output reg [31:0] min_sum, output reg done, output reg valid); reg [31:0] k_mem [1:64]; reg [31:0] E [0:7]; reg [63:0] numerator [0:7]; reg [63:0] denominator [0:7]; reg [2:0] iter_cnt; reg [3:0] state; reg [6:0] i_count; localparam IDLE = 4'd0, LOAD_K = 4'd1, INIT_E = 4'd2, ASSIGN = 4'd3, UPDATE = 4'd4, CALC_SUM = 4'd5, DONE = 4'd6; initial begin state <= IDLE; iter_cnt <=0; i_count <=0; E <=0; end always @(posedge clk) begin if (!rst_n) begin state <= IDLE; iter_cnt <=0; i_count <=0; E <=0; numerator <=0; denominator <=0; end else begin case (state) IDLE: if (start) state <= LOAD_K; else state <= IDLE; LOAD_K: state <= INIT_E; INIT_E: if (m >=1) E[0] = 1 <<16; if (m >=2) E[1] = 2 <<16; if (m >=3) E[2] = 3 <<16; if (m >=4) E[3] = 4 <<16; if (m >=5) E[4] = 5 <<16; if (m >=6) E[5] = 6 <<16; if (m >=7) E[6] = 7 <<16; if (m >=8) E[7] = 8 <<16; state <= ASSIGN; ASSIGN: if (i_count ==0) begin i_count <=1; numerator <=0; denominator <=0; end else begin int k_i = k_mem[i_count]; int cluster = i_count > m ? m-1 : i_count-1; numerator[cluster] <= numerator[cluster] + (k_i * i_count); denominator[cluster] <= denominator[cluster] + k_i; if (i_count == n) begin i_count <=0; state <= UPDATE; end else begin i_count <= i_count +1; end end UPDATE: reg [31:0] new_E [0:7]; int converged =1; if (m >=1) begin if (denominator[0] ==0) new_E[0] = E[0]; else new_E[0] = (numerator[0] <<16) / denominator[0]; if (new_E[0] != E[0]) converged =0; end if (m >=2) begin if (denominator[1] ==0) new_E[1] = E[1]; else new_E[1] = (numerator[1] <<16) / denominator[1]; if (new_E[1] != E[1]) converged =0; end if (m >=3) begin if (denominator[2] ==0) new_E[2] = E[2]; else new_E[2] = (numerator[2] <<16) / denominator[2]; if (new_E[2] != E[2]) converged =0; end if (m >=4) begin if (denominator[3] ==0) new_E[3] = E[3]; else new_E[3] = (numerator[3] <<16) / denominator[3]; if (new_E[3] != E[3]) converged =0; end if (m >=5) begin if (denominator[4] ==0) new_E[4] = E[4]; else new_E[4] = (numerator[4] <<16) / denominator[4]; if (new_E[4] != E[4]) converged =0; end if (m >=6) begin if (denominator[5] ==0) new_E[5] = E[5]; else new_E[5] = (numerator[5] <<16) / denominator[5]; if (new_E[5] != E[5]) converged =0; end if (m >=7) begin if (denominator[6] ==0) new_E[6] = E[6]; else new_E[6] = (numerator[6] <<16) / denominator[6]; if (new_E[6] != E[6]) converged =0; end if (m >=8) begin if (denominator[7] ==0) new_E[7] = E[7]; else new_E[7] = (numerator[7] <<16) / denominator[7]; if (new_E[7] != E[7]) converged =0; end if (converged || iter_cnt >=6) begin E <= new_E; iter_cnt <= iter_cnt +1; if (iter_cnt >6) begin state <= CALC_SUM; done <=1; valid <=0; end else begin state <= ASSIGN; end end else begin E <= new_E; iter_cnt <= iter_cnt +1; if (iter_cnt >=6) begin state <= CALC_SUM; done <=1; valid <=0; end else begin state <= ASSIGN; end end CALC_SUM: min_sum <=0; int i; for (i=1; i<=n; i++) begin int j = i >m ? m-1 : i-1; int e_val = E[j] >>16; min_sum <= min_sum + (k_mem[i] * (i - e_val)*(i - e_val)); end state <= DONE; valid <=1; end DONE: if (valid) state <= DONE; else state <= CALC_SUM; endcase end end always @(posedge clk) if (!rst_n) begin k_mem <=0; end else if (k_wr && bin_index>=1 && bin_index<=n) k_mem[bin_index] <= k_data; endmodule